package contour

import (
	"cmp"
	"encoding/json"
	"math"
	"os"
	"slices"
	"testing"

	"github.com/paulmach/orb"
)

// fixture is one case from testdata/fixtures.json, generated by contourpy with
// the settings isobands.py uses (see testdata/generate_fixtures.py).
type fixture struct {
	Name   string     `json:"name"`
	NX     int        `json:"nx"`
	NY     int        `json:"ny"`
	X      []float64  `json:"x"`
	Y      []float64  `json:"y"`
	Z      []*float64 `json:"z"` // null for NaN
	Levels []float64  `json:"levels"`
	Bands  []struct {
		Shells   int          `json:"shells"`
		Holes    int          `json:"holes"`
		Area     float64      `json:"area"`
		Vertices [][2]float64 `json:"vertices"`
		Polygons [][2]float64 `json:"polygons"` // [area, holes], sorted by holes then area
	} `json:"bands"`
}

func loadFixtures(t *testing.T) []fixture {
	t.Helper()
	data, err := os.ReadFile(`testdata/fixtures.json`)
	if err != nil {
		t.Fatal(err)
	}
	var fixtures []fixture
	if err = json.Unmarshal(data, &fixtures); err != nil {
		t.Fatal(err)
	}
	return fixtures
}

func (f fixture) grid() *Grid {
	z := make([]float64, len(f.Z))
	for i, v := range f.Z {
		z[i] = math.NaN()
		if v != nil {
			z[i] = *v
		}
	}
	return &Grid{NX: f.NX, NY: f.NY, X: f.X, Y: f.Y, Z: z}
}

func TestMatchesContourpy(t *testing.T) {
	for _, f := range loadFixtures(t) {
		t.Run(f.Name, func(t *testing.T) {
			topo, err := Contour(f.grid(), f.Levels)
			if err != nil {
				t.Fatal(err)
			}
			for k, want := range f.Bands {
				band := topo.Bands[k]
				shells, holes, area := len(band.Polygons), 0, 0.0
				vertices := make(map[[2]float64]bool)
				var polygons [][2]float64
				for _, polygon := range band.Polygons {
					holes += len(polygon.Holes)
					var polygonArea float64
					for _, ring := range topo.PolygonCoords(polygon) {
						polygonArea += shoelace(ring)
						for _, p := range ring {
							vertices[roundPoint(p)] = true
						}
					}
					area += polygonArea
					polygons = append(polygons, [2]float64{polygonArea, float64(len(polygon.Holes))})
				}
				if shells != want.Shells || holes != want.Holes {
					t.Errorf(`band %d: got %d shells and %d holes, contourpy has %d and %d`, k, shells, holes, want.Shells, want.Holes)
				}
				if math.Abs(area-want.Area) > 1e-9*math.Max(1, math.Abs(want.Area)) {
					t.Errorf(`band %d: got area %v, contourpy has %v`, k, area, want.Area)
				}
				if !samePolygons(polygons, want.Polygons) {
					t.Errorf(`band %d: got polygons [area, holes] %v, contourpy has %v`, k, polygons, want.Polygons)
				}
				missing, extra := compareVertices(vertices, want.Vertices)
				if len(missing) > 0 || len(extra) > 0 {
					t.Errorf(`band %d: %d contourpy vertices missing (e.g. %v), %d extra (e.g. %v)`, k, len(missing), first(missing), len(extra), first(extra))
				}
			}
		})
	}
}

// samePolygons compares [area, holes] pairs sorted by holes, then area, so
// near-equal areas that sort differently in Go and Python only swap polygons
// with the same number of holes.
func samePolygons(got, want [][2]float64) bool {
	slices.SortFunc(got, func(a, b [2]float64) int { return cmp.Or(cmp.Compare(a[1], b[1]), cmp.Compare(a[0], b[0])) })
	if len(got) != len(want) {
		return false
	}
	for i := range got {
		if got[i][1] != want[i][1] || math.Abs(got[i][0]-want[i][0]) > 1e-9*math.Max(1, want[i][0]) {
			return false
		}
	}
	return true
}

func shoelace(ring orb.Ring) float64 {
	var area float64
	for i := 0; i < len(ring)-1; i++ {
		area += ring[i][0]*ring[i+1][1] - ring[i+1][0]*ring[i][1]
	}
	return area / 2
}

// roundPoint rounds as the fixture generator does, so vertex sets compare.
func roundPoint(p orb.Point) [2]float64 {
	return [2]float64{math.Round(p[0]*1e9) / 1e9, math.Round(p[1]*1e9) / 1e9}
}

// compareVertices matches vertices within 2e-9, allowing for points that round
// to neighbouring values in Go and Python.
func compareVertices(got map[[2]float64]bool, want [][2]float64) (missing, extra [][2]float64) {
	const tolerance = 2e-9
	matched := make(map[[2]float64]bool)
	for _, w := range want {
		found := false
		for _, dx := range []float64{0, -1e-9, 1e-9} {
			for _, dy := range []float64{0, -1e-9, 1e-9} {
				p := roundPoint(orb.Point{w[0] + dx, w[1] + dy})
				if got[p] && math.Abs(p[0]-w[0]) <= tolerance && math.Abs(p[1]-w[1]) <= tolerance {
					matched[p], found = true, true
				}
			}
		}
		if !found {
			missing = append(missing, w)
		}
	}
	for p := range got {
		if !matched[p] {
			extra = append(extra, p)
		}
	}
	return missing, extra
}

func first(points [][2]float64) any {
	if len(points) == 0 {
		return nil
	}
	return points[0]
}
